import sys
from collections import deque

def solve():
    lines = sys.stdin.read().strip().split()
    idx = 0
    if idx < len(lines):
        N = int(lines[idx])
        idx += 1
    else:
        return

    if idx + 3 < len(lines):
        knight_x = int(lines[idx])
        knight_y = int(lines[idx+1])
        target_x = int(lines[idx+2])
        target_y = int(lines[idx+3])
    else:
        return

    if knight_x == target_x and knight_y == target_y:
        print(0)
        return

    moves = [
        (2, 1), (1, 2), (-1, 2), (-2, 1),
        (-2, -1), (-1, -2), (1, -2), (2, -1)
    ]

    visited = [[False] * (N + 1) for _ in range(N + 1)]
    queue = deque()
    queue.append((knight_x, knight_y, 0))
    visited[knight_x][knight_y] = True

    while queue:
        x, y, dist = queue.popleft()

        for dx, dy in moves:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= N and 1 <= ny <= N:
                if nx == target_x and ny == target_y:
                    print(dist + 1)
                    return
                if not visited[nx][ny]:
                    visited[nx][ny] = True
                    queue.append((nx, ny, dist + 1))

    print(-1)

if __name__ == "__main__":
    solve()
